def file_name_check(file_name):
    if not file_name or file_name.count('.') != 1:
        return 'No'

    before_dot, after_dot = file_name.split('.', 1)

    if len(before_dot) == 0 or not before_dot[0].isalpha():
        return 'No'

    if len(after_dot) == 0 or after_dot not in ['txt', 'exe', 'dll']:
        return 'No'

    digit_count = sum(c.isdigit() for c in file_name)

    return 'Yes' if digit_count <= 3 else 'No'

