    function CountDots(s: string): int
    {
        var count := 0;
        var i := 0;
        while i < s.Length
            invariant 0 <= count <= i
            invariant i <= s.Length
        {
            if s[i] == "." {
                count := count + 1;
            }
            i := i + 1;
        }
        count
    }

    function IsValidBeforeDot(s: string): bool
    {
        var dotIndex := s.IndexOf(".");
        if dotIndex <= 0 {
            return false;
        }
        return s[0] >= "a" && s[0] <= "z" || s[0] >= "A" && s[0] <= "Z";
    }

    function IsValidAfterDot(s: string): bool
    {
        var dotIndex := s.IndexOf(".");
        if dotIndex < 0 || dotIndex == s.Length - 1 {
            return false;
        }
        var extension := s.Substring(dotIndex + 1);
        return extension == "txt" || extension == "exe" || extension == "dll";
